CREATE PUBLIC TABLE __COLUMN(TableName String,ColumnName String,DataType Enum,Options Enum,NoNull Boolean,
                             Position Integer,DefinedBy Enum NoNull) USE RefreshPeriodMs="250" OnUndefColumn="REJECT" InitialCapacity="100";
CREATE INDEX pk ON __COLUMN(TableName SORT,ColumnName SORT) USE Constraint="PRIMARY";

CREATE PUBLIC TABLE __CONNECTION(AI Enum,EC Long,CI Long,MA Long,MC Long,
                                 O String,PL String,RI String,RP Long,RH String,
                                 CT Long) USE RefreshPeriodMs="250" OnUndefColumn="REJECT" InitialCapacity="100";

CREATE PUBLIC TABLE __DATASOURCE(NM String NoNull,AD String NoNull,UR String,US String,PW String,
                                 Password String,OP String,RelayId String,PermittedOverrides String) USE PersistEngine="TEXT" RefreshPeriodMs="250" OnUndefColumn="REJECT" InitialCapacity="100";
CREATE INDEX pk ON __DATASOURCE(NM SORT) USE Constraint="PRIMARY";

CREATE PUBLIC TABLE __DBO(DboName String NoNull,DboType String NoNull,Priority String NoNull,Options String,DefinedBy Enum NoNull,
                          Enabled Boolean NoNull) USE RefreshPeriodMs="250" OnUndefColumn="REJECT" InitialCapacity="100";
CREATE INDEX pk ON __DBO(DboName SORT) USE Constraint="PRIMARY";

CREATE PUBLIC TABLE __INDEX(IndexName String NoNull,TableName String NoNull,ColumnName String NoNull,IndexType Enum NoNull,IndexPosition String NoNull,
                            Constraint Enum NoNull,AutoGen Enum NoNull,DefinedBy Enum NoNull) USE RefreshPeriodMs="250" OnUndefColumn="REJECT" InitialCapacity="100";
CREATE INDEX pk ON __INDEX(TableName SORT,IndexName SORT,IndexPosition SORT) USE Constraint="PRIMARY";

CREATE PUBLIC TABLE __PROCEDURE(ProcedureName String NoNull,ProcedureType String NoNull,ReturnType String NoNull,Arguments String NoNull,Options String,
                                DefinedBy Enum NoNull) USE RefreshPeriodMs="250" OnUndefColumn="REJECT" InitialCapacity="100";
CREATE INDEX pk ON __PROCEDURE(ProcedureName SORT) USE Constraint="PRIMARY";

CREATE PUBLIC TABLE __RELAY(MachineUid String NoNull,ProcessUid String,StartTime UTC NoNull,ServerPort Integer,RelayId String,
                            Hostname String,ConnectTime UTC NoNull) USE RefreshPeriodMs="250" OnUndefColumn="REJECT" InitialCapacity="100";
CREATE INDEX relayId ON __RELAY(RelayId HASH) USE Constraint="NONE";
CREATE INDEX pk ON __RELAY(ProcessUid SORT) USE Constraint="PRIMARY";

CREATE PUBLIC TABLE __REPLICATION(ReplicationName String,TargetTable String,SourceCenter String,SourceTable String,Mapping String,
                                  Options String) USE PersistEngine="TEXT" RefreshPeriodMs="250" OnUndefColumn="REJECT" InitialCapacity="100";
CREATE INDEX pk ON __REPLICATION(ReplicationName SORT) USE Constraint="PRIMARY";

CREATE PUBLIC TABLE __STATS(Time UTC,E Long,UsedMemory Long,MaxMemory Long,PostGcUsedMemory Long,
                            RunningThreads Short,Rows Long,Events Long,Queries Long,UniqueUsers Short,
                            MaxUsers Short) USE RefreshPeriodMs="250" OnUndefColumn="REJECT" InitialCapacity="100";

CREATE PUBLIC TABLE __TABLE(TableName String NoNull,Broadcast Boolean NoNull,RefreshPeriodMs Long,PersistEngine Enum,OnUndefColumn Enum NoNull,
                            DefinedBy Enum NoNull,InitialCapacity Integer NoNull) USE RefreshPeriodMs="250" OnUndefColumn="REJECT" InitialCapacity="100";
CREATE INDEX pk ON __TABLE(TableName SORT) USE Constraint="PRIMARY";

CREATE PUBLIC TABLE __TIMER(TimerName String NoNull,TimerType String NoNull,Priority String NoNull,Schedule String NoNull,Options String,
                            DefinedBy Enum NoNull,LastRunTime UTC,NextRunTime UTC,Enabled Boolean NoNull) USE RefreshPeriodMs="250" OnUndefColumn="REJECT" InitialCapacity="100";
CREATE INDEX pk ON __TIMER(TimerName SORT) USE Constraint="PRIMARY";

CREATE PUBLIC TABLE __TRIGGER(TriggerName String NoNull,TableName String NoNull,TriggerType String NoNull,Priority String NoNull,Options String,
                              DefinedBy Enum NoNull,Enabled Boolean NoNull) USE RefreshPeriodMs="250" OnUndefColumn="REJECT" InitialCapacity="100";
CREATE INDEX pk ON __TRIGGER(TriggerName SORT) USE Constraint="PRIMARY";

CREATE PUBLIC TABLE ServerUsers(id Integer,server Integer,user Integer,options String,s_backend String,
                                s_user String,s_group Integer,s_groupname String,s_name String,s_frontend String,
                                s_msgline Integer,s_minorders Integer,NetBook String BITMAP) USE NoBroadcast RefreshPeriodMs="100" OnUndefColumn="REJECT" InitialCapacity="100";
